insert into public.refresh_runs (id, run_date, description, origin) values ('69793057-1158-5aa0-8f6e-088546ff8651', '2026-11-05', 'Partial refresh. Cevi Kreis 1 verified unchanged. Discovery searches covered Kreis 9 and cultural agendas Ron Orp, KiKuKa, kulturzüri. Three leads retained for verification in Kreise 2,4,9. Chreis+ ICS unsupported content type; GeoJSON inaccessible. Other source categories not fully checked. No deletions.', 'import:sqlite') on conflict do nothing;
